import com.ezylang.evalex.parser.Tokenizer;
import com.ezylang.evalex.config.ExpressionConfiguration;
import org.junit.Test;
import org.junit.Assert;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import com.ezylang.evalex.parser.Token;
import java.util.List;

public class TokenizerTest {

    @Test 
    public void createTokenizerTest() {
        ExpressionConfiguration expressionConfiguration = new ExpressionConfiguration();
        Tokenizer tokenizer = new Tokenizer("1+1", expressionConfiguration);
        Assert.assertNotNull(tokenizer);
    }

    @Test(expected = ParseException.class)
    public void parseExpressionWithInvalidCharacterTest() {
        ExpressionConfiguration configuration = new ExpressionConfiguration();
        Tokenizer tokenizer = new Tokenizer("1+@-3", configuration);
        tokenizer.parse();
    }

    @Test
    public void parseSimpleExpressionTest() {
        ExpressionConfiguration configuration = new ExpressionConfiguration();
        Tokenizer tokenizer = new Tokenizer("10*2/5", configuration);
        List<Token> tokens = tokenizer.parse();
        assertNotNull(tokens);
        assertEquals(5, tokens.size());
        assertEquals("10", tokens.get(0).surface);
        assertEquals("*", tokens.get(1).surface);
        assertEquals("2", tokens.get(2).surface);
        assertEquals("/", tokens.get(3).surface);
        assertEquals("5", tokens.get(4).surface);
    }

    @Test
    public void parseExpressionWithFunctionTest() {
        ExpressionConfiguration configuration = new ExpressionConfiguration();
        Tokenizer tokenizer = new Tokenizer("5+MAX(2,3)*10", configuration);
        List<Token> tokens = tokenizer.parse();
        assertNotNull(tokens);
        assertEquals(7, tokens.size());
        assertEquals("5", tokens.get(0).surface);
        assertEquals("+", tokens.get(1).surface);
        assertEquals("MAX", tokens.get(2).surface);
        assertEquals("2", tokens.get(3).surface);
        assertEquals(",", tokens.get(4).surface);
        assertEquals("3", tokens.get(5).surface);
        assertEquals("*", tokens.get(6).surface);
        assertEquals("10", tokens.get(7).surface);
    }

    @Test(expected = ParseException.class)
    public void parseStringLiteralInvalidFormatTest() {
        ExpressionConfiguration configuration = new ExpressionConfiguration();
        Tokenizer tokenizer = new Tokenizer("'testStr", configuration);
        tokenizer.parseStringLiteral();
    }

    @Test
    public void parseStringLiteralValidFormatTest() {
        ExpressionConfiguration configuration = new ExpressionConfiguration();
        Tokenizer tokenizer = new Tokenizer("'testStr'", configuration);
        Token token = tokenizer.parseStringLiteral();
        assertNotNull(token);
        assertEquals(TokenType.StringLiteral, token.type);
        assertEquals("testStr", token.surface);
    }
}
